<?php
declare(strict_types=1);
require __DIR__.'/amazon-recovery-testlib.php';require __DIR__.'/../includes/amazon-recovery/gmail-source.php';
$enc=static fn(string $s):string=>rtrim(strtr(base64_encode($s),'+/','-_'),'=');$msg=['id'=>'m1','threadId'=>'t1','internalDate'=>'1788250000000','payload'=>['headers'=>[['name'=>'From','value'=>'donotreply@amazon.com'],['name'=>'Subject','value'=>'Reembolso de 128.25 BRL iniciado para o pedido 701-1433354-4637803']],'mimeType'=>'multipart/alternative','parts'=>[['mimeType'=>'text/plain','body'=>['data'=>$enc("Prezado vendedor\nPedido 701-1433354-4637803")]],['mimeType'=>'text/html','body'=>['data'=>$enc('<p>html</p>')]]]]];$ex=sv_ar_gmail_extract_full_message($msg);ar_t_eq('m1',$ex['id'],'message id');ar_t_eq('donotreply@amazon.com',$ex['from'],'from');ar_t_assert(str_contains($ex['subject'],'Reembolso de 128.25 BRL'),'subject');ar_t_assert(str_contains($ex['body'],'Pedido 701-1433354-4637803'),'plain body decoded');ar_t_assert(str_contains(sv_ar_gmail_default_query(),'amazon'),'query scoped to Amazon');ar_t_ok('Gmail source MIME extraction');
